mapper.insert:
INSERT INTO tb_audit_log (
    user_seq, actor_user_id, actor_name, action_type,
    target_table, target_key, reason, client_ip, request_id
) VALUES (
    #{userSeq}, #{actorUserId}, #{actorName}, #{actionType},
    #{targetTable}, #{targetKey}, #{reason}, #{clientIp}, #{requestId}
)

mapper.select:
SELECT l.log_seq, l.user_seq, l.actor_user_id, l.actor_name, l.action_type, l.target_table, l.target_key, l.reason, l.client_ip, l.request_id, l.occurred_at, c.code_name AS action_name, (SELECT COUNT(*) FROM tb_audit_log_detail d WHERE d.log_seq = l.log_seq) AS changed_column_count FROM tb_audit_log l LEFT JOIN tb_code_group g ON g.code_group_id = 'AUDIT_ACTION' LEFT JOIN tb_code c ON c.code_group_seq = g.code_group_seq AND c.code_id = l.action_type
ORDER BY l.occurred_at DESC, l.log_seq DESC
LIMIT #{size} OFFSET #{offset}
